function forChannel(text) {
  const url = ($env.NOTIFY_WEBHOOK_URL || '').trim();
  let payload = text, contentType = 'text/plain';
  if (url.includes('discord.com/api/webhooks') || url.includes('discordapp.com/api/webhooks')) {
    payload = JSON.stringify({ content: text.slice(0, 1900), allowed_mentions: { parse: [] } });
    contentType = 'application/json';
  } else if (url.includes('hooks.slack.com')) {
    payload = JSON.stringify({ text });
    contentType = 'application/json';
  }
  return { json: { url, contentType, payload, text } };
}

const e = $json.body || $json;
const c = e.clip || e;
const who = c.creator ? c.creator.name : '';
const title = c.title || `clip ${c.clip_id}`;
const flagLines = (c.needs_human || []).map(f => `• ${f.detail}`).join('\n');
const L = (c.links || {}), PL = (e.links || {});
let text = null;
switch (e.event) {
  case 'clip.needs_review':
    text = `Needs review: ${title} (${who}, ${c.duration}s)\n${flagLines || '• first clips from a new streamer get a human look'}\nReview: ${L.review}`;
    break;
  case 'clip.ready':
    text = `Clip queued to post: ${title} (${who}, ${c.duration}s)`;
    break;
  case 'post.export_ready': {
    const cap = ((c.copy || {})[e.platform] || {}).caption || '';
    text = `Ready to post by hand on ${e.platform}: ${title}\nCaption:\n${cap}\nVideo: ${PL.video}\nMark it posted: ${PL.posts}`;
    break;
  }
  case 'post.published':
    text = `Live on ${e.platform}: ${title} ${e.remote_url || ''}`;
    break;
  case 'post.failed':
    text = `Post FAILED on ${e.platform}: ${title}\n${e.error || ''}\n${PL.posts}`;
    break;
  case 'job.failed':
    text = `Rolecall ${e.stage} failed: ${e.error}`;
    break;
  case 'source.ingested':
    text = `New VOD from ${e.creator}: ${e.title || e.url}`;
    break;
  case 'prospects.found': {
    const lines = (e.prospects || []).map((p, i) =>
      `${i + 1}. ${p.name} (${p.platform}, ${p.peak_viewers || '?'} viewers, fit ${p.score}) ${p.url}\n   Invite: ${p.invite_text}`);
    text = `${e.count} GTA 6 streamer(s) worth inviting. Send the invite on their socials, then mark them invited: ${(e.links || {}).prospects}\n` + lines.join('\n');
    break;
  }
}
if (!text) return [];
return [forChannel(`[Rolecall] ${text}`)];
